@require_POST
def trigger_repo_security_scan(request):
    data = json.loads(request.body)
    repo_id = data.get('repo_id')
    get_object_or_404(Repository, id=repo_id, organization=request.user.organization)
    webhook_url = data.get('notify_url')
    clone_and_audit_repo_task.delay(repository_id=repo_id, notify_url=webhook_url)
